def _linux_redhat_release():
    """Try to determine the name of a Linux distribution.

    This function checks for the /etc/redhat-release file.
    It takes the name from the first line and the version from the second line.
    An empty string is returned if the above values cannot be determined.
    """
    try:
        with open("/etc/redhat-release") as redhat_release:
            name = redhat_release.readline().strip()
